// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(bool _payRoyalties) public {
        // 1. Admissible domain: any bool
        // 2. Drive initialize with _payRoyalties; succeed must be true
        bool success;
        try c.initialize(
            address(0),
            address(this),
            1,
            1,
            0,
            0,
            bytes32(0),
            false,
            _payRoyalties
        ) {
            success = true;
        } catch {
            success = false;
        }
        require(success, "initialize failed");

        // 3. General rule: if _payRoyalties is true, c.payRoyalties() must return true
        if (_payRoyalties) {
            assertTrue(c.payRoyalties());
        }
    }
}

